/* cad_analysis.h: a cad-brep analysis buffer (what is derived from one model buffer, tied to it by the model's
 * SHA-256) for C and C++ readers. Generated by packages/cad-brep/gen/header.ts from
 * packages/cad-brep/src/analysis-layout.ts, which documents every table and column; don't edit. The format is
 * cad_brep.h's (the magic, a uint32 column count, then per column, enum cba_column, its byte offset and
 * element count, then the columns, each 8-byte aligned), and cba_open assumes what cbr_open does. A per-entity
 * table (vertex, edge, coedge, face, surface, shell) is empty or has the model's rows; checking that, and the
 * hash, is the caller's. */
#ifndef CAD_ANALYSIS_H
#define CAD_ANALYSIS_H

#include <stddef.h>
#include <stdint.h>
#include <string.h>

#define CBA_MAGIC "CBA3"
#define CBA_HEADER_BYTES 384

/* The columns in buffer order: table, column, element type and values per row. */
enum cba_column {
  CBA_ANALYSIS_MODEL, /* uint32_t x 8 */
  CBA_ANALYSIS_UNCERTAINTY, /* double x 1 */
  CBA_POOL_REAL, /* double x 1 */
  CBA_POOL_INT, /* int32_t x 1 */
  CBA_VERTEX_MEASURED, /* double x 1 */
  CBA_VERTEX_FIRST, /* int32_t x 1 */
  CBA_VERTEX_COUNT, /* int32_t x 1 */
  CBA_VERTEX_TOLERANCE_FROM, /* uint8_t x 1 */
  CBA_VERTEX_GIVEN_TOLERANCE, /* double x 1 */
  CBA_EDGE_RANGE, /* double x 2 */
  CBA_EDGE_RANGE_FROM, /* uint8_t x 1 */
  CBA_EDGE_MEASURED, /* double x 1 */
  CBA_EDGE_FIRST, /* int32_t x 1 */
  CBA_EDGE_COUNT, /* int32_t x 1 */
  CBA_EDGE_TOLERANCE_FROM, /* uint8_t x 1 */
  CBA_EDGE_GIVEN_TOLERANCE, /* double x 1 */
  CBA_COEDGE_RANGE, /* double x 2 */
  CBA_COEDGE_RANGE_FROM, /* uint8_t x 1 */
  CBA_COEDGE_DEVIATION, /* double x 1 */
  CBA_COEDGE_FACE, /* int32_t x 1 */
  CBA_COEDGE_LOOP, /* int32_t x 1 */
  CBA_COEDGE_PCURVE_FROM, /* uint8_t x 1 */
  CBA_COEDGE_TRACE_STATUS, /* uint8_t x 1 */
  CBA_COEDGE_TRACE_TOL, /* double x 1 */
  CBA_COEDGE_OFF_SURFACE, /* double x 1 */
  CBA_COEDGE_STOP_AT, /* double x 1 */
  CBA_COEDGE_STOP_WHY, /* uint8_t x 1 */
  CBA_FACE_OUTER_LOOP, /* int32_t x 1 */
  CBA_FACE_OUTER_FROM, /* uint8_t x 1 */
  CBA_FACE_UV, /* double x 4 */
  CBA_FACE_AREA, /* double x 2 */
  CBA_FACE_AREA_FROM, /* uint8_t x 1 */
  CBA_SURFACE_U_CLOSED, /* uint8_t x 1 */
  CBA_SURFACE_V_CLOSED, /* uint8_t x 1 */
  CBA_SURFACE_U_PERIOD, /* double x 1 */
  CBA_SURFACE_V_PERIOD, /* double x 1 */
  CBA_SURFACE_FIRST, /* int32_t x 1 */
  CBA_SURFACE_COUNT, /* int32_t x 1 */
  CBA_CONTINUITY_EDGE, /* int32_t x 1 */
  CBA_CONTINUITY_A, /* int32_t x 1 */
  CBA_CONTINUITY_B, /* int32_t x 1 */
  CBA_CONTINUITY_CLASS, /* uint8_t x 1 */
  CBA_CONTINUITY_ANGLE, /* double x 1 */
  CBA_CONTINUITY_ANGLE_ERROR, /* double x 1 */
  CBA_SHELL_VOLUME, /* double x 2 */
  CBA_SHELL_FACING, /* uint8_t x 1 */
  CBA_SHELL_FACING_FROM, /* uint8_t x 1 */
  CBA_COLUMN_COUNT
};

enum cba_provenance {
  CBA_PROVENANCE_NONE = 0,
  CBA_PROVENANCE_GIVEN = 1,
  CBA_PROVENANCE_MEASURED = 2,
  CBA_PROVENANCE_HEALED = 3,
};

enum cba_measure_trust {
  CBA_TRUST_NONE = 0,
  CBA_TRUST_ESTIMATE = 1,
  CBA_TRUST_EXACT = 2,
};

enum cba_continuity {
  CBA_CONTINUITY_UNKNOWN = 0,
  CBA_CONTINUITY_C0 = 1,
  CBA_CONTINUITY_G1 = 2,
  CBA_CONTINUITY_G2 = 3,
};

enum cba_singularity {
  CBA_SINGULARITY_POLE = 0,
  CBA_SINGULARITY_APEX = 1,
  CBA_SINGULARITY_NORMAL_VANISHES = 2,
};

enum cba_facing {
  CBA_FACING_UNKNOWN = 0,
  CBA_FACING_OUT = 1,
  CBA_FACING_IN = 2,
};

enum cba_facing_from {
  CBA_FACING_FROM_NONE = 0,
  CBA_FACING_FROM_VOLUME = 1,
  CBA_FACING_FROM_CLASSIFICATION = 2,
  CBA_FACING_FROM_BOTH = 3,
};

enum cba_logical {
  CBA_LOGICAL_FALSE = 0,
  CBA_LOGICAL_TRUE = 1,
  CBA_LOGICAL_UNKNOWN = 2,
};

/* One column: its values and their count (rows times its width). */
typedef struct {
  const void* data;
  uint32_t count;
} cba_view;

/* The columns of a buffer of `size` bytes into `views` (CBA_COLUMN_COUNT of them): 0, or -1 if it isn't one. */
static inline int cba_open(const uint8_t* buf, size_t size, cba_view* views) {
  static const uint8_t bytes[CBA_COLUMN_COUNT] = {
    4, 8, 8, 4, 8, 4, 4, 1, 8, 8, 1, 8, 4, 4, 1, 8, 8, 1, 8, 4, 4, 1, 1, 8, 8, 8, 1, 4, 1, 8, 8, 1, 1, 1, 8, 8, 4, 4, 4,
    4, 4, 1, 8, 8, 8, 1, 1,
  };
  uint32_t n, k;
  if (((uintptr_t)buf & 7) != 0 || size < CBA_HEADER_BYTES || memcmp(buf, CBA_MAGIC, 4) != 0) return -1;
  memcpy(&n, buf + 4, 4);
  if (n != CBA_COLUMN_COUNT) return -1;
  for (k = 0; k < n; k++) {
    uint32_t offset, count;
    memcpy(&offset, buf + 8 + 8 * k, 4);
    memcpy(&count, buf + 12 + 8 * k, 4);
    if ((offset & 7) != 0 || offset < CBA_HEADER_BYTES || offset > size
      || (uint64_t)count * bytes[k] > size - offset) return -1;
    views[k].data = buf + offset;
    views[k].count = count;
  }
  return 0;
}

#define CBA_U8(v) ((const uint8_t*)(v).data)
#define CBA_I32(v) ((const int32_t*)(v).data)
#define CBA_U32(v) ((const uint32_t*)(v).data)
#define CBA_F64(v) ((const double*)(v).data)

#endif
